import {renderSkillPixelIcon} from './skill-pixel-icons.js';
import {DWARF_EXPANDED_DESCRIPTIONS as SKILL_TREE_DESCRIPTIONS} from './dwarf-skill-expansion.js';
import {DWARF_EXPANDED_DEFINITION as DEFAULT_DEFINITION} from './dwarf-skill-expansion.js';
import {normalizeSkillTree,skillPointBudget,skillPresetCost,validSkillTree} from './skill-tree-state.js';
import {icon} from './icons.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nodeNames=(ids,definition)=>ids.map(id=>definition.nodes.find(n=>n.id===id)?.name??id).join('、');
import {skillConditionChoices,effectiveSkillCondition,skillConditionNotice,skillConditionWeapon,skillConditionSetCounts} from './skill-conditions.js';
// Registry definitions supply named groups and optional coordinates. Unknown catalogs
// still render a DAG: depth follows all prerequisites, never array order.
export function skillTreeGroups(definition){
 if(definition.groups)return definition.groups;
 if(definition.id===DEFAULT_DEFINITION.id)return [
 {id:'steel',name:'裂岩战技',ids:['fracture_strike','fault_sweep','breach_followup','axe_fervor','hammer_penetration']},
 {id:'fire',name:'炉火战技',ids:['ember_brand','furnace_wave','cinder_barrage','fire_affinity']},
 {id:'guard',name:'守势战技',ids:['iron_vigil','bastion_blow','repelling_wave','shield_reserve']},
 {id:'shared',name:'共通战技',ids:['anvil_cry','breaking_intercept','furnace_etch','scatter_ash','forge_breath','purifying_bulwark','mountain_vitality','forged_resilience']}];
 const buckets=new Map();for(const n of definition.nodes){const key=n.branch??'shared';if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(n.id);}
 return [...buckets].map(([id,ids])=>({id,name:id==='shared'?'共通战技':id,ids}));
}
export function skillTreeGeometry(definition,group){
 const depth=new Map(),getDepth=id=>{if(depth.has(id))return depth.get(id);const n=definition.nodes.find(n=>n.id===id),d=n.requires.length?1+Math.max(...n.requires.map(getDepth)):0;depth.set(id,d);return d;};
 const rows=new Map();const nodes=group.ids.map(id=>definition.nodes.find(n=>n.id===id)).filter(Boolean).map(n=>{const row=n.row??getDepth(n.id),col=n.column??(rows.get(row)??0);rows.set(row,(rows.get(row)??0)+1);return {id:n.id,x:col*160+10,y:row*146+10,width:140,height:108};});
 const positions=new Map(nodes.map(n=>[n.id,n])),edges=[];
 for(const item of nodes){const n=definition.nodes.find(n=>n.id===item.id);for(const from of n.requires){const a=positions.get(from);if(a){const edge={from,to:n.id,x1:a.x+70,y1:a.y+108,x2:item.x+70,y2:item.y};const lane=a.x<170?a.x+150:a.x-10;edge.path=item.y-a.y>146?`M ${edge.x1} ${edge.y1} V ${edge.y1+17} H ${lane} V ${edge.y2-17} H ${edge.x2} V ${edge.y2}`:`M ${edge.x1} ${edge.y1} V ${(edge.y1+edge.y2)/2} H ${edge.x2} V ${edge.y2}`;edges.push(edge);}}}
 return {nodes,edges,width:Math.max(480,...nodes.map(n=>n.x+150)),height:Math.max(184,...nodes.map(n=>n.y+132))};
}
const treeFingerprint=s=>JSON.stringify({skillTree:s.skillTree,skills:s.skills,conditions:s.conditions,loadouts:s.loadouts});
const conditionGear=(s,index)=>index!==s.skillTree.selectedPreset&&s.loadouts?.[index]?.equip?{...s,equip:s.loadouts[index].equip}:s;
export function renderSkillTree(m){
 const D=m.definition??DEFAULT_DEFINITION,groups=skillTreeGroups(D),names=ids=>nodeNames(ids,D);
 const gear=conditionGear(m.draft,m.index),weaponType=skillConditionWeapon(gear),setCounts=skillConditionSetCounts(gear);
 const p=m.draft.skillTree.presets[m.index],budget=skillPointBudget(m.draft),spent=skillPresetCost(p,D),blocked=m.busy;
 const status=m.conflict?'配置已在其他位置变化，请取消草稿后重新编辑。':m.error||(m.blocked?'可预先加点；结束当前战斗并停止远征后确认应用。':budget===0?'升级获得技能点。初始普通攻击无需解锁。':'点击技能解锁，确认应用后生效。');
 const commitButton=()=>`<button class="primary" data-tree-action="commit" ${blocked||m.blocked||m.conflict||m.refund?'disabled':''}>${m.busy?'正在保存…':'确认应用'}</button>`;
 const card=(id,position)=>{const n=D.nodes.find(n=>n.id===id),learned=p.unlocked.includes(id),missing=n.requires.filter(key=>!p.unlocked.includes(key)),available=!missing.length&&spent+n.cost<=budget;const reason=learned?'退还技能点':missing.length?'需先学习 '+names(missing):!available?`还需 ${spent+n.cost-budget} 点`:'解锁技能';return `<article class="treeNodeCard ${m.inspect===id?'selected':''}" data-tree-branch-node="${id}" style="left:${position.x}px;top:${position.y}px"><button class="treeNode ${learned?'learned':available?'available':'locked'}" data-tree-action="inspect" data-tree-id="${id}" aria-pressed="${m.inspect===id}" aria-label="查看${esc(n.name)} · ${learned?'已解锁':available?'可解锁':'未满足条件'} · ${n.cost}点" title="${esc(n.name)} · 查看效果与前置"><span class="treeNodeArt">${renderSkillPixelIcon(id)}${!learned&&!available?'<span class="skillPixelLock" aria-hidden="true"></span>':''}</span><strong>${esc(n.name)}</strong><small>${n.kind==='passive'?'被动':'主动'} · ${n.cost}点</small></button><button class="treeQuickAction" data-tree-action="node" data-tree-id="${id}" ${blocked||m.conflict||!learned&&!available?'disabled':''} aria-label="${esc(n.name)} · ${esc(reason)}" title="${esc(reason)}">${learned?'−':'+'}</button></article>`;};

 return `<section class="skillTreeEditor"><header><div><h2>战技树 · 方案${m.index+1}</h2><span>已用 ${spent} / ${budget} 点 · 全树99点</span></div><strong class="treePointBalance">剩余 ${budget-spent} 点</strong>${commitButton()}</header><div class="treeStatusBar"><p class="treeStatus" role="status">${esc(status)}</p>${m.blocked&&m.draft.running?`<button data-stopafter="1" ${m.busy||m.stopRequested?'disabled':''}>${m.stopRequested?'等待本次挑战结束':m.inDungeon?'本次副本结束后停止':'本场结束后停止'}</button>`:''}</div><nav>${m.draft.skillTree.presets.map((q,i)=>`<button data-tree-action="plan" data-tree-id="${i}" aria-pressed="${i===m.index}" ${blocked?'disabled':''}>${esc(q.name)}${i===m.draft.skillTree.selectedPreset?' · 当前':''}</button>`).join('')}</nav>${m.refund?`<aside class="treeReview" tabindex="-1" role="region" aria-label="确认退还技能点"><h3>确认退还 ${m.refund.points} 点？</h3><p>将退还：${esc(names(m.refund.ids))}。相关主动/被动将出槽，不自动替补。</p><button data-tree-action="refund-confirm" ${blocked?'disabled':''}>确认退还至草稿</button><button data-tree-action="refund-cancel">取消退款</button></aside>`:''}<div class="treeGraphToolbar"><span>连线表示全部必需前置 · 金色已学 / 青色可学 / 灰色锁定</span><label>查看分支 <select data-tree-view="branch"><option value="all">全树</option>${groups.map(g=>`<option value="${g.id}" ${m.branch===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><span>可横向滚动查看完整树</span></div><div class="treeGraphViewport" tabindex="0" aria-label="可滚动技能树"><div class="treeBranches ${m.branch&&m.branch!=='all'?'isFiltered':''}">${[...groups].sort((a,b)=>(b.id==='shared')-(a.id==='shared')).filter(g=>!m.branch||m.branch==='all'||g.id===m.branch).map(g=>{const geometry=skillTreeGeometry(D,g);return `<section class="treeBranch treeBranch-${g.id}" aria-label="${esc(g.name)}" style="width:${geometry.width+24}px"><h3>${esc(g.name)}</h3><div class="treeNodes" style="width:${geometry.width}px;height:${geometry.height}px"><svg class="treeEdges" width="${geometry.width}" height="${geometry.height}" aria-hidden="true">${geometry.edges.map(e=>`<path data-tree-edge="${e.from}:${e.to}" class="${p.unlocked.includes(e.to)?'learned':p.unlocked.includes(e.from)?'available':'locked'}" d="${e.path}"/>`).join('')}</svg>${geometry.nodes.map(n=>card(n.id,n)).join('')}</div></section>`;}).join('')}</div></div>${m.inspect?(()=>{const n=D.nodes.find(n=>n.id===m.inspect);if(!n)return '';const raw=(m.descriptions??SKILL_TREE_DESCRIPTIONS)[n.id],d=typeof raw==='string'?{base:raw}:raw;return `<aside class="treeSelection" aria-live="polite" aria-label="技能详情"><button class="treeDetailClose" data-tree-action="inspect-close" aria-label="关闭技能详情">×</button><h3>${esc(n.name)} · ${n.cost}点</h3><p>剩余 ${budget-spent} 点 · 前置：${esc(names(n.requires)||'无')} · ${p.unlocked.includes(n.id)?'已解锁':n.requires.some(id=>!p.unlocked.includes(id))?'前置未满足':spent+n.cost>budget?'点数不足':'可以解锁'}</p><button data-tree-action="node" data-tree-id="${n.id}" ${blocked||m.conflict||!p.unlocked.includes(n.id)&&(n.requires.some(id=>!p.unlocked.includes(id))||spent+n.cost>budget)?'disabled':''}>${p.unlocked.includes(n.id)?'退还至草稿':`解锁 · ${n.cost}点`}</button>${[d?.base,d?.axe,d?.hammer].filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('')}${n.kind==='passive'?'<p>仅装入两个被动槽之一后生效。</p>':''}</aside>`;})():''}<div class="treeSlots">${['active','passive'].map(kind=>`<section class="treeSlotSection treeSlotSection-${kind}"><h3>${kind==='active'?'主动技能':'被动技能'}</h3><p>${kind==='active'?'按 1 → 4 的优先级释放':'装入后生效'}</p>${p[kind].map((value,i)=>`<div class="treeSlot treeSlot-${kind}">${renderSkillPixelIcon(value)}<label class="treeSlotChoice"><span>${kind==='active'?'主动':'被动'} ${i+1}</span><select aria-label="${kind==='active'?'主动':'被动'}${i+1}技能" data-tree-slot="${kind}" data-tree-index="${i}" ${blocked||m.conflict?'disabled':''}><option value="">留空</option>${D.nodes.filter(n=>n.kind===kind&&p.unlocked.includes(n.id)).map(n=>`<option value="${n.id}" ${value===n.id?'selected':''} ${p[kind].includes(n.id)&&value!==n.id?'disabled':''}>${esc(n.name)}</option>`).join('')}</select></label>${kind==='active'?`<label class="treeSlotCondition"><span>释放条件</span><select aria-label="主动${i+1}释放条件" data-tree-condition="${i}" ${blocked||m.conflict?'disabled':''}>${skillConditionChoices(value,weaponType,setCounts).map(([id,label])=>`<option value="${id}" ${effectiveSkillCondition(p.conditions[i],value,weaponType,setCounts)===id?'selected':''}>${label}</option>`).join('')}</select>${skillConditionNotice(p.conditions[i],value,weaponType,setCounts)?`<small class="treeConditionNotice" role="status">${esc(skillConditionNotice(p.conditions[i],value,weaponType,setCounts))}<button type="button" data-tree-action="condition-reset" data-tree-id="${i}" ${blocked||m.conflict?'disabled':''}>改为可用即施放</button></small>`:''}</label>`:''}</div>`).join('')}</section>`).join('')}</div><footer><button data-tree-action="reset" ${blocked||m.conflict?'disabled':''}>免费重置本方案</button><button data-tree-action="cancel" ${m.busy?'disabled':''}>取消草稿</button>${commitButton()}</footer></section>`;
}
export function mountSkillTree(host,adapter){let disposed=false,m,D;
 const reset=()=>{const live=adapter.getState(),draft=structuredClone(live);D=adapter.getDefinition?.(live)??DEFAULT_DEFINITION;if(!normalizeSkillTree(draft,D))throw Error('invalid skill tree');m={definition:D,descriptions:adapter.getDescriptions?.(live),branch:'all',inspect:null,baseState:structuredClone(live),draft,index:draft.skillTree.selectedPreset,beforeTree:structuredClone(live.skillTree??null),busy:false,blocked:false,activationAllowed:adapter.canActivate!==false,error:'',refund:null,activationReview:false};};
 let lastLiveKey='';
 const syncLive=()=>{const live=adapter.getState();m.blocked=!!live.running||!!live.dungeonRun||!!live.activeEncounter&&!live.activeEncounter.done;m.conflict=treeFingerprint(live)!==treeFingerprint(m.baseState);m.inDungeon=!!live.dungeonRun;m.stopRequested=!!live.stopAfterBattle||!!live.stopAfterDungeon;m.draft.running=!!live.running;m.draft.equip=structuredClone(live.equip);m.draft.inventory=structuredClone(live.inventory);
 // Level-ups may occur while drafting. Rebase only the earned-point budget; never adopt changed allocations.
 if(!m.conflict){m.baseState.level=live.level;m.draft.level=live.level;}
 lastLiveKey=JSON.stringify([live.level,m.blocked,!!live.dungeonRun,!!live.stopAfterBattle,!!live.stopAfterDungeon,treeFingerprint(live),skillConditionWeapon(live),skillConditionSetCounts(live)]);};
 const paint=()=>{if(disposed)return;const view=host.querySelector?.('.treeGraphViewport'),scroll=view?{left:view.scrollLeft,top:view.scrollTop}:null;syncLive();host.innerHTML=renderSkillTree(m);const next=host.querySelector?.('.treeGraphViewport');if(scroll&&next){next.scrollLeft=scroll.left;next.scrollTop=scroll.top;}};
 const refresh=()=>{if(disposed)return;const live=adapter.getState(),blocked=!!live.running||!!live.dungeonRun||!!live.activeEncounter&&!live.activeEncounter.done,key=JSON.stringify([live.level,blocked,!!live.dungeonRun,!!live.stopAfterBattle,!!live.stopAfterDungeon,treeFingerprint(live),skillConditionWeapon(live),skillConditionSetCounts(live)]);if(key!==lastLiveKey)paint();};
 const changeDraft=fn=>{const next=structuredClone(m.draft);fn(next.skillTree.presets[m.index]);if(!validSkillTree(next,D)){m.error='配置无效：请检查前置、点数与重复技能';return false;}m.draft=next;m.error='';m.activationReview=false;return true;};
 // Refunds affect only this editor draft; the normal Apply transaction owns persistence.
 const applyRefund=()=>{if(!m.refund)return;const ids=m.refund.ids;changeDraft(p=>{p.unlocked=p.unlocked.filter(id=>!ids.includes(id));p.active=p.active.map((id,i)=>{if(ids.includes(id)){p.conditions[i]='always';return null;}return id;});p.passive=p.passive.map(id=>ids.includes(id)?null:id);});m.refund=null;};
 const refund=(ids,confirm=false)=>{let set=new Set(ids),p=m.draft.skillTree.presets[m.index];for(let previous=-1;previous!==set.size;){previous=set.size;for(const n of D.nodes)if(p.unlocked.includes(n.id)&&n.requires.some(id=>set.has(id)))set.add(n.id);}const list=p.unlocked.filter(id=>set.has(id));m.refund={ids:list,points:D.nodes.filter(n=>list.includes(n.id)).reduce((a,n)=>a+n.cost,0)};if(!confirm&&list.length===1)applyRefund();};
 const commit=async activate=>{syncLive();if(m.busy||m.blocked||m.conflict)return;m.busy=true;m.error='';paint();try{const result=await adapter.commit({baseState:structuredClone(m.baseState),beforeTree:structuredClone(m.beforeTree),presets:structuredClone(m.draft.skillTree.presets),activate});if(disposed)return;if(result?.ok){reset();m.error='已保存';}else m.error=result?.reason||'保存失败，草稿保留；未应用变更';}catch{m.error='保存失败，草稿保留；未应用变更';}finally{m.busy=false;paint();}};
 const click=async ev=>{const b=ev.target.closest('[data-tree-action]');if(!b||!host.contains(b)||b.disabled)return;const action=b.dataset.treeAction;paint();if(action==='inspect-close'){m.inspect=null;paint();return;}if(m.busy)return;if(action==='cancel'){reset();adapter.onCancel?.();paint();return;}if(m.conflict)return;
 if(action==='condition-reset'){const i=Number(b.dataset.treeId);if(Number.isInteger(i)&&i>=0&&i<4)changeDraft(p=>p.conditions[i]='always');}
 if(action==='inspect')m.inspect=b.dataset.treeId;
 if(action==='plan'){const i=Number(b.dataset.treeId);if(Number.isInteger(i)&&i>=0&&i<3){m.index=i;m.refund=null;m.activationReview=false;}}
 if(action==='node'){m.inspect=b.dataset.treeId;const n=D.nodes.find(n=>n.id===b.dataset.treeId);if(n){if(m.draft.skillTree.presets[m.index].unlocked.includes(n.id))refund([n.id]);else changeDraft(p=>p.unlocked.push(n.id));}}
 if(action==='reset')refund([...m.draft.skillTree.presets[m.index].unlocked],true);
 if(action==='refund-cancel')m.refund=null;
 if(action==='refund-confirm'&&m.refund)applyRefund();
 if(action==='activate-cancel')m.activationReview=false;
 if(action==='commit'&&!m.refund)await commit(false);if(action==='activate-review'&&m.activationAllowed&&!m.refund&&m.draft.skillTree.mode!=='active')m.activationReview=true;
 if(action==='activate-confirm'&&m.activationReview)await commit(true);paint();if(m.refund&&(action==='node'||action==='reset')){const review=host.querySelector?.('.treeReview');review?.focus?.({preventScroll:true});review?.scrollIntoView?.({block:'nearest',behavior:'auto'});}};
 const change=ev=>{const t=ev.target;syncLive();if(m.busy||m.conflict||!host.contains(t))return;if(t.dataset.treeView==='branch'){m.branch=t.value;paint();return;}const kind=t.dataset.treeSlot,index=Number(t.dataset.treeIndex);if(['active','passive'].includes(kind)&&Number.isInteger(index)&&index>=0&&index<(kind==='active'?4:2))changeDraft(p=>p[kind][index]=t.value||null);if(t.dataset.treeCondition!==undefined){const i=Number(t.dataset.treeCondition);if(Number.isInteger(i)&&i>=0&&i<4&&skillConditionChoices(m.draft.skillTree.presets[m.index].active[i],skillConditionWeapon(conditionGear(m.draft,m.index)),skillConditionSetCounts(conditionGear(m.draft,m.index))).some(([id])=>id===t.value))changeDraft(p=>p.conditions[i]=t.value);}paint();};
 const keydown=ev=>{if(ev.key==='Escape'&&m.inspect){m.inspect=null;paint();}};
 reset();paint();host.addEventListener('click',click);host.addEventListener('change',change);host.addEventListener('keydown',keydown);return {refresh,getDraft:()=>structuredClone(m.draft),dispose(){disposed=true;host.removeEventListener?.('click',click);host.removeEventListener?.('change',change);host.removeEventListener?.('keydown',keydown);}};
}
